ll gcd(ll a, ll b) { if (a == 0 || b == 0) return (a + b); if (a > b) return (gcd(a%b, b)); return (gcd(b, b % a)); }

#define Nmax 1000009
#define INF 1000000007
#define y1 yy1
#define eps 1e-5
void out() { std::cout << "NO\n"; exit(0); }
using namespace std;

int n, T, a[101];
bool used[101];

int main(){
	//freopen("input.txt", "r", stdin);
	//freopen("output.txt", "w", stdout);

	cin >> n;
	FOR(i, 0, n) cin >> a[i];
	cin >> T;

	int ans = 0;
	sort(a, a + n);
	FOR(i, 0, n) {
		int p = i+1;
		while (p < n && abs(a[i] - a[p]) <= T) p++;
		ans = max(ans, p - i);
	}
	cout << ans << endl;

	return 0;
}
